class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        n = len(s)
        from functools import lru_cache

        def palCost(i, j):
            c = 0
            while i < j:
                if s[i] != s[j]:
                    c += 1
                i += 1
                j -= 1
            return c

        @lru_cache(maxsize=None)
        def f(i, m):
            if m == 1:
                return palCost(i, n - 1)
            if n - i == m:
                return 0
            best = float('inf')
            for j in range(i, n - m + 1):
                best = min(best, palCost(i, j) + f(j + 1, m - 1))
            return best

        return f(0, k)

