            if (s[i] != s[j]) c++;
            i++; j--;
        }
        return c;
    }

    int f(int i, int m) {
        if (m == 1) return palCost(i, n - 1);
        if (n - i == m) return 0;
        int &res = memo[i][m];
        if (res != -1) return res;
        res = INT_MAX;
        for (int j = i; j <= n - m; j++)
            res = min(res, palCost(i, j) + f(j + 1, m - 1));
        return res;
    }

    int palindromePartition(string str, int k) {
        s = str;
        n = s.size();
        memo.assign(n, vector<int>(k + 1, -1));
        return f(0, k);
    }
};

