class Solution {
    private int n;
    private String s;
    private Integer[][] memo;

    private int palCost(int i, int j) {
        int c = 0;
        while (i < j) {
            if (s.charAt(i) != s.charAt(j)) c++;
            i++; j--;
        }
        return c;
    }

    private int f(int i, int m) {
        if (m == 1) return palCost(i, n - 1);
        if (n - i == m) return 0;
        if (memo[i][m] != null) return memo[i][m];
        int res = Integer.MAX_VALUE;
        for (int j = i; j <= n - m; j++)
            res = Math.min(res, palCost(i, j) + f(j + 1, m - 1));
        return memo[i][m] = res;
    }

    public int palindromePartition(String str, int k) {
        s = str;
        n = s.length();
        memo = new Integer[n][k + 1];
        return f(0, k);
    }
}

