    const memo = new Map();

    const palCost = (i, j) => {
        let c = 0;
        while (i < j) {
            if (s[i] !== s[j]) c++;
            i++; j--;
        }
        return c;
    };

    const f = (i, m) => {
        if (m === 1) return palCost(i, n - 1);
        if (n - i === m) return 0;
        const key = i * 1000 + m;
        if (memo.has(key)) return memo.get(key);
        let best = Infinity;
        for (let j = i; j <= n - m; j++)
            best = Math.min(best, palCost(i, j) + f(j + 1, m - 1));
        memo.set(key, best);
        return best;
    };

    return f(0, k);
};

